public void initValue(NDXProdIdentControlPanelContract _contract = new NDXProdIdentControlPanelContract())
{
    this.NDXCreatedBy = _contract.ParmNDXCreatedBy(curUserId());
    this.NDXCreatedDateTime = _contract.ParmNDXCreatedDateTime(DateTimeUtil::utcNow());
    this.Active = _contract.ParmActive(NoYes::Yes);
    this.BTRecordIdPrefix = _contract.ParmBTRecordIdPrefix(NDXProdIdentUKParameters::find().BTRecordIdPrefix());
}

