/// <summary>
/// PaffH 15.05.23
/// </summary>
/// <param name = "_responseLabelSaved2DatabaseContract">ResponseLabelSaved2DatabaseContract</param>
public static void processFromResponseLabelSaved2DatabaseContract(Niedax.AzureServiceBus.Models.PALabel.ResponseLabelSaved2DatabaseContract _responseLabelSaved2DatabaseContract)
{
    NDXProdIdentControlPanel nDXProdIdentControlPanel;
    Niedax.AzureServiceBus.Models.PALabel.NDXProdIdentControlPanelContract nDXProdIdentControlPanelContract;
    IEnumerable tList = _responseLabelSaved2DatabaseContract.NDXProdStatusChangedGenerateTransportLabelEventContract.ProdIdentControlPanelLines;
    IEnumerator enum = tList.GetEnumerator();
    ttsbegin;
    while (enum.moveNext())
    {
        nDXProdIdentControlPanelContract = enum.current;
        if (nDXProdIdentControlPanelContract.RecIdNDXProdIdentControlPanel != 0)
        {
            nDXProdIdentControlPanel = NDXProdIdentControlPanel::findRecId(nDXProdIdentControlPanelContract.RecIdNDXProdIdentControlPanel, true);
            if (nDXProdIdentControlPanel)
            {
                nDXProdIdentControlPanel.BT_StatusDateTime = DateTimeUtil::removeTimeZoneOffset(nDXProdIdentControlPanelContract.BT_StatusDateTime, DateTimeUtil::getCompanyTimeZone());
                nDXProdIdentControlPanel.BT_StatusUserId = nDXProdIdentControlPanelContract.BT_StatusUserId;
                nDXProdIdentControlPanel.BT_Status = NDXProdIdentBTStatus::BTRecordInserted;
                nDXProdIdentControlPanel.LastChecked = DateTimeUtil::utcNow();
                nDXProdIdentControlPanel.update();
            }
        }
    }
    ttscommit;
}

/// <summary>
/// PaffH 05.05.23
/// refresh list of NDXProdIdentControlPanelContract with actual NDXProdIdentControlPanel
/// </summary>
/// <param name = "_list">list with NDXProdIdentControlPanelContract</param>
/// <param name = "_setBTRecordId">boolean</param>
/// <returns>refreshed list with NDXProdIdentControlPanelContract</returns>
public static List refreshListWithContracts(List _list, boolean _setBTRecordId = true)
{
    List listNDXProdIdentControlPanelContract = new List(Types::Class);
    ListEnumerator enum = _list.getEnumerator();
    while (enum.moveNext())
    {
        if (enum.current() is NDXProdIdentControlPanelContract)
        {
            NDXProdIdentControlPanelContract contract = enum.current() as NDXProdIdentControlPanelContract;
            NDXProdIdentControlPanel nDXProdIdentControlPanel = NDXProdIdentControlPanel::findRecId(contract.ParmRefRecIdNDXProdIdentControlPanel(), true);
            if (_setBTRecordId && nDXProdIdentControlPanel.BTAction == NDXProdIdentBTAction::delete
                || nDXProdIdentControlPanel.BTAction == NDXProdIdentBTAction::insert
                || nDXProdIdentControlPanel.BTAction == NDXProdIdentBTAction::update)
            {
                ttsbegin;
                nDXProdIdentControlPanel.BT_RecordId = NDXProdIdentParameters::nextRecordId();
                nDXProdIdentControlPanel.update();
                ttscommit;
            }
            listNDXProdIdentControlPanelContract.addEnd(NDXProdIdentControlPanel::populateToContract(nDXProdIdentControlPanel));
        }
    }
    return listNDXProdIdentControlPanelContract;
}

