/// <summary>
/// PaffH 03.01.25
/// AX2009: tables.NDX_ProdIdentControlPanel.fillFromProdRouteJob()
/// </summary>
void fillFromProdRouteJob()
{
    Query   q = new Query();
    QueryRun    qr;
    QueryBuildDataSource    qbds1, qbds2;

    ProdRoute       prodRoute;
    ProdRouteJob    prodRouteJob;
    container   conJobId;

    qbds1 = q.addDataSource(tablenum(ProdRoute));
    qbds1.addRange(fieldnum(ProdRoute, ProdId)).value(this.ProdId);
    qbds1.addRange(fieldnum(ProdRoute, OprPriority)).value(QueryValue(RouteOprPriority::Primary));
    qbds2 = qbds1.addDataSource(tablenum(ProdRouteJob));
    qbds2.joinMode(JoinMode::InnerJoin);
    qbds2.relations(true);
    qbds2.fetchMode(QueryFetchMode::One2One);
    qbds2.addRange(fieldnum(ProdRouteJob, JobType)).value(QueryValue(RouteJobType::Setup));
    qbds2.addRange(fieldnum(ProdRouteJob, JobType)).value(QueryValue(RouteJobType::Process));
    qr = new QueryRun(q);
    while (qr.next())
    {
        prodRouteJob = qr.get(tablenum(ProdRouteJob));
        conJobId += prodRouteJob.JobId;
    }
    this.PAJobIds = Con2Str(conJobId);
}

/// <summary>
/// PaffH 10.05.22
/// </summary>
/// <param name = "_recId">RecId</param>
/// <param name = "_forUpdate">boolean</param>
/// <returns>NDXProdIdentControlPanel</returns>
static public NDXProdIdentControlPanel findRecId(RecId _recId, boolean _forUpdate = false)
{
    NDXProdIdentControlPanel   nDXProdIdentControlPanel;

    nDXProdIdentControlPanel.selectForUpdate(_forUpdate);

    select firstonly nDXProdIdentControlPanel
        where nDXProdIdentControlPanel.RecId == _recId;

    return nDXProdIdentControlPanel;
}

