/// <summary>
/// PaffH 04.07.22
/// AX2009: tables.NDX_ProdIdentControlPanel::findProcedureLine2()
/// </summary>
/// <param name = "prodId">ProdId</param>
/// <param name = "refRecIdProdIdent_ProcedureLine2">RefRecId</param>
/// <param name = "update">boolean</param>
/// <returns>NDXProdIdentControlPanel</returns>
static NDXProdIdentControlPanel findProcedureLine2(ProdId  prodId,
                                  RefRecId refRecIdProdIdent_ProcedureLine2,
                                  boolean update = false)
{
    NDXProdIdentControlPanel prodIdentControlPanel;
    ;
    prodIdentControlPanel.selectForUpdate(update);

    select firstonly prodIdentControlPanel
    where prodIdentControlPanel.ProdId          == prodId    &&
          prodIdentControlPanel.RefRecIdProdIdent_ProcedureLine2 == refRecIdProdIdent_ProcedureLine2;

    return prodIdentControlPanel;
}

/// <summary>
/// PaffH 05.07.22
/// AX2009: tables.NDX_ProdIdentControlPanel.genBarcodeString()
/// </summary>
/// <param name = "getBarcodeStr">boolean</param>
/// <returns>BarCodeString</returns>
static BarCodeString genBarcodeString(boolean getBarcodeStr = true)
{
    Barcode          barcode = Barcode::construct(BarcodeType::Interleaved2of5);
    BarCodeString    barCodeString;
    System.Random random;                   
    System.Int32 int321, int322;            
    InteropPermission permission;           
    ;
    sleep(10);

    permission = new InteropPermission(InteropKind::ClrInterop);
    permission.assert();

    // BP deviation documented
    random = new System.Random();
    int321 = random.Next(1000000,9999999);
    int322 = random.Next(1000000,9999999);
    barCodeString =  int321.ToString();
    barCodeString += int322.ToString();

    CodeAccessPermission::revertAssert();
    if (!barcode.validateBarcode(barcode.string(true, barCodeString)))
    {
        return '';
    }
    return getBarcodeStr ? barcode.barcodeStr() : barcode.barcodeStrHR();
}

