void fillFromBlock2ItemId(NDXProdIdentProcedureLine2 lNDX_ProdIdent_ProcedureLine2)
{

    NDXProdIdentBlock2ItemId      nDX_ProdIdent_Block2ItemId;

    Query                   q;
    QueryRun                qr;
    QueryBuildDataSource    qbds1, qbds2;

    q = new Query();

    qbds1 = q.addDataSource(tablenum(NDXProdIdentBlock2ItemId));
    qbds1.addRange(fieldnum(NDXProdIdentBlock2ItemId, FreeTextField)).value(SysQuery::valueNotEmptyString());
    qbds2 = qbds1.addDataSource(tablenum(NDXProdIdentProcedureLine2));
    qbds2.joinMode(JoinMode::InnerJoin);
    qbds2.fetchMode(QueryFetchMode::One2One);
    qbds2.relations(true);
    qbds2.addRange(fieldnum(NDXProdIdentProcedureLine2, RecId)).value(QueryValue(lNDX_ProdIdent_ProcedureLine2.RecId));
    QueryBuildDataSource qbdsNDXProdIdentBlockTable = qbds1.addDataSource(tableNum(NDXProdIdentBlockTable));
    qbdsNDXProdIdentBlockTable.joinMode(JoinMode::InnerJoin);
    qbdsNDXProdIdentBlockTable.fetchMode(QueryFetchMode::One2One);
