/// <summary>
/// PaffH 07.07.2022
/// AX2009: tables.NDX_ProdIdentControlPanel.findItemIdProdBOM
/// </summary>
/// <param name = "itemidProdBOM">ItemId</param>
/// <param name = "oprNum">OprNum</param>
/// <param name = "prodId">ProdId</param>
/// <param name = "update">boolean</param>
/// <returns>NDXProdIdentControlPanel</returns>
static NDXProdIdentControlPanel findItemIdProdBOM(ItemId itemidProdBOM,
                                  OprNum    oprNum,
                                  ProdId    prodId,
                                  boolean update = false)
{
    NDXProdIdentControlPanel nDX_prodIdentControlPanel;
    ;
    nDX_prodIdentControlPanel.selectForUpdate(update);

    select firstonly nDX_prodIdentControlPanel
    where nDX_prodIdentControlPanel.ItemIdProdBOM   == itemidProdBOM    &&
          nDX_prodIdentControlPanel.OprNum          == oprNum           &&
          nDX_prodIdentControlPanel.ProdId          == prodId;

    return nDX_prodIdentControlPanel;
}

/// <summary>
/// PaffH 04.05.23
/// on multiple entries adjust BT_Action and ToSync
/// AX2009:tables.NDX_ProdIdentControlPanel::setSyncActionDiffDataFrom
/// </summary>
/// <param name = "prodId">ProdId</param>
/// <param name = "controlPanelDataFrom">NDXProdIdentControlPanelDataFrom</param>
static void setSyncActionDiffDataFrom(ProdId prodId, NDXProdIdentControlPanelDataFrom controlPanelDataFrom = NDXProdIdentControlPanelDataFrom::BoxLabelMapping)
{
    NDXProdIdentControlPanel       nDXProdIdentControlPanel;

    Query   q = new Query();
    QueryRun    qr;
    QueryBuildDataSource    qbds;
    ;
    qbds = q.addDataSource(tablenum(NDXProdIdentControlPanel));
    qbds.update(true);
    qbds.addRange(fieldnum(NDXProdIdentControlPanel, ProdId)).value(prodId);
    qbds.addRange(fieldnum(NDXProdIdentControlPanel, ControlPanelDataFrom)).value(QueryValue(controlPanelDataFrom));
    qbds.addRange(fieldnum(NDXProdIdentControlPanel, DiffDataFrom)).value(QueryValue(true));
    qr = new QueryRun(q);
    while (qr.next())
    {
        nDXProdIdentControlPanel = qr.get(tablenum(NDXProdIdentControlPanel));
        if (nDXProdIdentControlPanel.ToSync == NoYes::Yes)
        {
            ttsbegin;
            nDXProdIdentControlPanel.ToSync    = NoYes::No;
            nDXProdIdentControlPanel.BTAction = NDXProdIdentBTAction::noActionMulitple;
            nDXProdIdentControlPanel.doUpdate();
            ttscommit;
        }
    }
}

/// <summary>
/// PaffH 05.05.23
/// check PA's with different data collection methods
/// AX2009: tables.NDX_ProdIdentControlPanel.checkDiffDataFrom()
/// </summary>
/// <param name = "_nDXProdIdentControlPanel">NDXProdIdentControlPanel</param>
/// <param name = "_lWithInfo">boolean</param>
static void checkDiffDataFrom(NDXProdIdentControlPanel _nDXProdIdentControlPanel = null, boolean _lWithInfo = false)
{
    NDXProdIdentControlPanel   nDXProdIdentControlPanel;
    NDXProdIdentControlPanel   nDXProdIdentControlPanelGrp;
    Set set;
    counter i;
    counter countDiffDataFrom;
    counter countDiffs;
    Query   q1;
    QueryRun    qr1;
    QueryBuildDataSource    qbds1;

    if (_lWithInfo)
    {
        info(strfmt("@NDX:NDXEmaminationOfDiffCollectMethods", NDXHelperCommon::seconds2Str(), "@NDXBase:NDXStart", ''));
    }
    q1 = new Query();
    qbds1 = q1.addDataSource(tablenum(NDXProdIdentControlPanel));
    qbds1.addGroupByField(fieldnum(NDXProdIdentControlPanel, ProdId));
    qbds1.addSelectionField(fieldnum(NDXProdIdentControlPanel, RecId), SelectionField::Count);
    if (_nDXProdIdentControlPanel)
    {
        if (!_nDXProdIdentControlPanel.ProdId)
        {
            return;
        }
        qbds1.addRange(fieldnum(NDXProdIdentControlPanel, ProdId)).value(_nDXProdIdentControlPanel.ProdId);
    }
    qr1 = new QueryRun(q1);
    while (qr1.next())
    {
        nDXProdIdentControlPanelGrp = qr1.get(tablenum(NDXProdIdentControlPanel));
        if (nDXProdIdentControlPanelGrp.RecId == 1)
        {
            select firstonly nDXProdIdentControlPanel
            where   nDXProdIdentControlPanel.ProdId == nDXProdIdentControlPanelGrp.ProdId;
            if (nDXProdIdentControlPanel.DiffDataFrom)
            {
                nDXProdIdentControlPanel.selectForUpdate(true);
                ttsbegin;
                nDXProdIdentControlPanel.DiffDataFrom = false;
                nDXProdIdentControlPanel.doUpdate();
                ttscommit;
                ++countDiffs;
            }
        }
        else
        {
            set = new Set(Types::Enum);
            i = 0;
            countDiffDataFrom = 0;
            while select nDXProdIdentControlPanel
            where    nDXProdIdentControlPanel.ProdId == nDXProdIdentControlPanelGrp.ProdId
            {
                ++i;
                if (nDXProdIdentControlPanel.DiffDataFrom)
                {
                    ++countDiffDataFrom;
                }
                set.add(nDXProdIdentControlPanel.ControlPanelDataFrom);
            }
            if (set.elements() == 1)        // keine unterschiedlichen Ermittlungsverfahren
            {
                if (countDiffDataFrom)
                {
                    while select forUpdate nDXProdIdentControlPanel
                    where   nDXProdIdentControlPanel.ProdId == nDXProdIdentControlPanelGrp.ProdId
                        &&  nDXProdIdentControlPanel.DiffDataFrom
                    {
                        ttsbegin;
                        nDXProdIdentControlPanel.DiffDataFrom = false;
                        nDXProdIdentControlPanel.doupdate();
                        ttscommit;
                        ++countDiffs;
                    }
                }
            }
            else    // unterschiedliche Ermittlungsverfahren
            {
                if (countDiffDataFrom != i)
                {
                    while select forUpdate nDXProdIdentControlPanel
                    where   nDXProdIdentControlPanel.ProdId == nDXProdIdentControlPanelGrp.ProdId
                        &&  !nDXProdIdentControlPanel.DiffDataFrom
                    {
                        ttsbegin;
                        nDXProdIdentControlPanel.DiffDataFrom = true;
                        nDXProdIdentControlPanel.doupdate();
                        ttscommit;
                        ++countDiffs;
                    }
                }
            }
        }
    }
    if (_lWithInfo)
    {
        info(strfmt("@NDX:NDXEmaminationOfDiffCollectMethods", NDXHelperCommon::seconds2Str(), "@NDXBase:NDXEnd", strfmt("@NDXBase:NDXDifference01", countDiffs)));
    }

}

/// <summary>
/// PaffH 05.05.23
/// AX2009: tables.NDX_ProdIdentControlPanel.insert()
/// </summary>
public void insert()
{
    this.ProdIdentControlPanelId = this.ProdIdentControlPanelManual == NoYes::Yes ? this.ProdIdentManualId : this.ProdId;
    super();
    if (!this.isTmp())
    {
        NDXProdIdentControlPanel::checkDiffDataFrom(this, false); 
    }
}

/// <summary>
/// PaffH 05.05.23
/// AX2009: tables.NDX_ProdIdentControlPanel.update()
/// </summary>
public void update()
{
    this.ProdIdentControlPanelId = this.ProdIdentControlPanelManual == NoYes::Yes ? this.ProdIdentManualId : this.ProdId;
    super();
    if (!this.isTmp())
    {
        NDXProdIdentControlPanel::checkDiffDataFrom(this, false);
    }
}

/// <summary>
/// PaffH 19.09.24
/// check unique ProdIdentControlPanelId
/// </summary>
/// <returns>int</returns>
public static int checkProdIdentControlPanelIdAll()
{
    Counter recordsChanged = 0;
    NDXProdIdentControlPanel nDXProdIdentControlPanel;
    ttsbegin;
    while select forupdate nDXProdIdentControlPanel
        where nDXProdIdentControlPanel.ProdIdentControlPanelManual == NoYes::Yes
        && nDXProdIdentControlPanel.ProdIdentControlPanelId != nDXProdIdentControlPanel.ProdIdentManualId
    {
        nDXProdIdentControlPanel.ProdIdentControlPanelId = nDXProdIdentControlPanel.ProdIdentManualId;
        nDXProdIdentControlPanel.update();
        ++recordsChanged;
    }
    while select forupdate nDXProdIdentControlPanel
        where nDXProdIdentControlPanel.ProdIdentControlPanelManual == NoYes::No
        && nDXProdIdentControlPanel.ProdIdentControlPanelId != nDXProdIdentControlPanel.ProdId
    {
        nDXProdIdentControlPanel.ProdIdentControlPanelId = nDXProdIdentControlPanel.ProdId;
        nDXProdIdentControlPanel.update();
        ++recordsChanged;
    }
    ttscommit;
    return recordsChanged;
}

/// <summary>
/// PaffH 05.05.23
/// AX2009: tables.NDX_ProdIdentControlPanel.delete()
/// </summary>
public void delete()
{
    NDXProdIdentControlPanel   lNDX_ProdIdentControlPanel;

    try
    {
        super();

        if (!this.isTmp() && this.DiffDataFrom)
        {
            select firstOnly lNDX_ProdIdentControlPanel
            where   lNDX_ProdIdentControlPanel.ProdId == this.ProdId;
            if (lNDX_ProdIdentControlPanel)
            {
                NDXProdIdentControlPanel::checkDiffDataFrom(lNDX_ProdIdentControlPanel, false);
            }
        }
    }
    catch
    {
        error(strfmt("@NDX:NDXProdIdRecId", this.ProdId, this.RecId));
    }
}

/// <summary>
/// PaffH 05.05.23
/// AX2009: tables.NDX_ProdIdentControlPanel.modifiedField()
/// </summary>
/// <param name = "_fieldId">fieldId</param>
public void modifiedField(fieldId _fieldId)
{
    super(_fieldId);


    if (_fieldId != fieldnum(NDXProdIdentControlPanel, ToSync) && this.ToSync == NoYes::No)
    {
        this.ToSync = NoYes::Yes;

        if (this.BTAction == NDXProdIdentBTAction::noAction)
        {
            if (this.BT_RecordId)
            {
                this.BTAction  = NDXProdIdentBTAction::update;
            }
            else
            {
                this.BTAction  = NDXProdIdentBTAction::insert;
            }
        }
    }
    switch (_fieldId)
    {
        case fieldnum(NDXProdIdentControlPanel, BTAction):
            if (this.BT_RecordId && this.BTAction == NDXProdIdentBTAction::insert)
            {
                Warning(strfmt("@NDXBase:NDXAppendNotPossibleRecordExists", this.BT_RecordId));
                this.BTAction = NDXProdIdentBTAction::update;
            }
            break;
        case fieldnum(NDXProdIdentControlPanel, ProdIdentControlPanelManual):
        case fieldnum(NDXProdIdentControlPanel, ProdId):
        case fieldnum(NDXProdIdentControlPanel, ProdIdentManualId):
            this.ProdIdentControlPanelId = this.ProdIdentControlPanelManual == NoYes::Yes ? this.ProdIdentManualId : this.ProdId;
            break;
    }
}

/// <summary>
/// PaffH 05.08.24
/// </summary>
/// <param name = "_prodId">ProdId</param>
/// <returns>NDXBTPAWithBTLabelRef</returns>
public static NDXBTPAWithBTLabelRef existsProdTable(ProdId _prodId)
{
    NDXProdIdentControlPanel nDXProdIdentControlPanel;
    select firstonly RecId from nDXProdIdentControlPanel
        where nDXProdIdentControlPanel.ProdId == _prodId;
    return nDXProdIdentControlPanel.RecId > 0 ? NoYes::Yes : NoYes::No;
}
